class MaxFlowSolver:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1]))
    def compute_levels(self, s):
        from collections import deque
        self.levels = [-1] * self.n
        self.levels[s] = 0
        queue = deque([s])
        while queue:
            v = queue.popleft()
            for to, cap, rev in self.graph[v]:
                if cap > 0 and self.levels[to] < 0:
                    self.levels[to] = self.levels[v] + 1
                    queue.append(to)
    def send_flow(self, v, t, flow):
        if v == t:
            return flow
        for i in range(self.it[v], len(self.graph[v])):
            self.it[v] = i
            to, cap, rev = self.graph[v][i]
            if cap > 0 and self.levels[v] < self.levels[to]:
                pushed = self.send_flow(to, t, min(flow, cap))
                if pushed > 0:
                    self.graph[v][i][1] -= pushed
                    self.graph[to][rev][1] += pushed
                    return pushed
        return 0
    def max_flow(self, s, t):
        total = 0
        while True:
            self.compute_levels(s)
            if self.levels[t] < 0:
                return total
            self.it = [0] * self.n
            while True:
                pushed = self.send_flow(s, t, 10**9)
                if pushed == 0:
                    break
                total += pushed

